import type { Metadata } from 'next'

const SITE_NAME = 'Tofa Kimani Portfolio'

/**
 * Per-page metadata. Next merges metadata shallowly, so a page that sets only
 * `title` still shares the home page's og:title / twitter:title — link
 * previews of /skills or /cv would read like the home page. This sets them
 * together, plus a canonical URL. A page-level openGraph object also
 * replaces the inherited preview image, so the one generated by
 * app/opengraph-image.tsx is set explicitly.
 */
const image = { url: '/opengraph-image', width: 1200, height: 630, alt: 'Tofa Kimani Mwangi — Software Engineer' }

export function pageMetadata({ title, description, path }: { title: string; description: string; path: string }): Metadata {
  const full = `${title} | Tofa Kimani`
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { type: 'website', locale: 'en_US', siteName: SITE_NAME, url: path, title: full, description, images: [image] },
    twitter: { card: 'summary_large_image', title: full, description, images: [image.url] },
  }
}
